/* HID protocol tests. Every expected packet below was worked out by hand from the frame layout in km_hid.h
 * (header, cmd, xor key, checksum = len + offsets + sum(data), len, offset LE, data), not generated by the code under test. */
#include "km/km_flash_map.h"
#include "km/km_hid.h"
#include "km_test.h"

typedef struct {
    const char *name;
    int         kind;       /* 0 read, 1 write, 3 boot erase, 4 boot write, 5 boot verify, 6 boot finish */
    uint8_t     cmd;
    uint32_t    offset;
    uint8_t     len;
    const char *data_hex;
    const char *pkt_hex;    /* only the leading bytes; the rest of the 64-byte packet is zero */
} vector_t;

static const vector_t k_vectors[] = {
    { "read base 0/56",         0, 0x04, 0,      56, "",         "55040038" "38000000" },
    { "read trigger 1024/56",   0, 0xA0, 1024,   56, "",         "55a0003c" "38000400" },        /* 56 + 0x00 + 0x04 */
    { "read trigger 4080/16",   0, 0xA0, 4080,   16, "",         "55a0000f" "10f00f00" },        /* 16 + 0xF0 + 0x0F = 0x10F */
    { "read keymap 4608/56",    0, 0x08, 4608,   56, "",         "5508004a" "38001200" },        /* 56 + 0x00 + 0x12 */
    { "read calibration 0/56",  0, 0xAA, 0,      56, "",         "55aa0038" "38000000" },
    { "write 4 bytes at 0x428", 1, 0xA1, 0x428,  4,  "01020304", "55a1003a" "04280400" "01020304" },  /* 4 + 0x28 + 0x04 + 10 */
    { "write high bytes",       1, 0x09, 0x1200, 3,  "ff8001",   "55090095" "03001200" "ff8001" },   /* 3 + 0x12 + 0xFF + 0x80 + 1 = 0x195 */
    { "write 2 bytes at 0",     1, 0x0E, 0,      2,  "0301",     "550e0006" "02000000" "0301" },     /* 2 + 3 + 1 */
    { "boot erase 19F5:AF1F",   3, 0x81, 0,      0,  "",         "8107f5191faf00" },
    { "boot write 3 bytes @96", 4, 0x80, 96,     3,  "010203",   "800360000000" "010203" },
    { "boot verify @0x38000",   5, 0x82, 0x38000, 2, "a1b2",     "8202" "00800300" "a1b2" },
    { "boot end",               6, 0x83, 0,      0,  "",         "8301" },
    { "boot done",              6, 0x84, 0,      0,  "",         "8401" },
};

static void hex_of(const uint8_t *p, size_t n, char *out)
{
    for (size_t i = 0; i < n; i++) {
        sprintf(out + 2 * i, "%02x", p[i]);
    }
}

void test_hid(void)
{
    /* Every hand-computed packet equals what our builders produce, and the device-side parser reads it back. */
    for (size_t i = 0; i < sizeof k_vectors / sizeof k_vectors[0]; i++) {
        const vector_t *v = &k_vectors[i];
        uint8_t data[64] = { 0 };
        uint8_t want[KM_HID_REPORT_LEN] = { 0 };
        uint8_t out[KM_HID_REPORT_LEN];
        char got[2 * KM_HID_REPORT_LEN + 1], exp[2 * KM_HID_REPORT_LEN + 1];
        km_hid_status_t st = KM_HID_ERR_ARG;
        km_hex(v->data_hex, data, sizeof data);
        km_hex(v->pkt_hex, want, sizeof want);
        hex_of(want, sizeof want, exp);

        switch (v->kind) {
        case 0: st = km_hid_build_read(out, v->cmd, (uint16_t)v->offset, v->len); break;
        case 1: st = km_hid_build_write(out, v->cmd, (uint16_t)v->offset, data, v->len); break;
        case 3: st = km_boot_build_erase(out, 0x19F5, 0xAF1F); break;
        case 4: st = km_boot_build_chunk(out, KM_BOOT_WRITE, v->offset, data, v->len); break;
        case 5: st = km_boot_build_chunk(out, KM_BOOT_VERIFY, v->offset, data, v->len); break;
        case 6: st = km_boot_build_finish(out, (km_boot_cmd_t)v->cmd); break;
        default: break;
        }
        hex_of(out, sizeof out, got);
        if (st != KM_HID_OK || strcmp(got, exp) != 0) {
            printf("  vector '%s' mismatch\n    got  %s\n    want %s\n", v->name, got, exp);
        }
        CHECK(st == KM_HID_OK && strcmp(got, exp) == 0);

        /* Device side: 'U' packets parse and give back the same fields. */
        if (v->kind <= 1) {
            km_hid_req_t req;
            CHECK(km_hid_parse(want, &req) == KM_HID_OK);
            CHECK_EQ(req.cmd, v->cmd);
            CHECK_EQ(req.len, v->len);
            CHECK_EQ(req.offset, v->offset);
            if (v->kind != 0) {
                CHECK(memcmp(req.data, data, v->len) == 0);
            }
        }
    }

    /* The enter-boot packet, literally (BOOTLOADER_ANALYSIS.md section 1, flag byte). */
    {
        uint8_t out[KM_HID_REPORT_LEN];
        static const uint8_t want[9] = { 0x5F, 0x06, 0x00, 0x52, 0x01, 0x00, 0x00, 0x00, 0x51 };
        CHECK(km_hid_build_enter_boot(out) == KM_HID_OK);
        CHECK(memcmp(out, want, 9) == 0);
        for (int i = 9; i < 64; i++) { CHECK_EQ(out[i], 0); }
    }

    /* XOR: bytes [3..7+len] are masked, the header, cmd and key stay in the clear. */
    {
        uint8_t out[KM_HID_REPORT_LEN], plain[KM_HID_REPORT_LEN];
        km_hid_req_t req;
        static const uint8_t data[5] = { 1, 2, 3, 4, 5 };
        CHECK(km_hid_build(plain, KM_HID_HDR_NORMAL, 0x09, 0, 0x0123, false, data, 5) == KM_HID_OK);
        CHECK(km_hid_build(out, KM_HID_HDR_NORMAL, 0x09, 0x5A, 0x0123, false, data, 5) == KM_HID_OK);
        CHECK_EQ(out[0], 0x55);
        CHECK_EQ(out[1], 0x09);
        CHECK_EQ(out[2], 0x5A);
        for (int i = 3; i <= 12; i++) { CHECK_EQ(out[i], plain[i] ^ 0x5A); }
        for (int i = 13; i < 64; i++) { CHECK_EQ(out[i], 0); }
        CHECK(km_hid_parse(out, &req) == KM_HID_OK);
        CHECK_EQ(req.xor_key, 0x5A);
        CHECK_EQ(req.cmd, 0x09);
        CHECK_EQ(req.len, 5);
        CHECK_EQ(req.offset, 0x0123);
        CHECK(memcmp(req.data, data, 5) == 0);
        /* Raw packets are never XORed even when a key is requested. */
        CHECK(km_hid_build(out, KM_HID_HDR_RAW, 0x06, 0x77, 0, false, data, 1) == KM_HID_OK);
        CHECK_EQ(out[2], 0);
    }

    /* Error paths. */
    {
        uint8_t out[KM_HID_REPORT_LEN];
        km_hid_req_t req;
        static const uint8_t data[8] = { 9, 8, 7, 6, 5, 4, 3, 2 };
        CHECK(km_hid_build_write(out, 0x09, 0, data, 8) == KM_HID_OK);
        out[8] ^= 0x01;                                            /* corrupt the payload */
        CHECK(km_hid_parse(out, &req) == KM_HID_ERR_CHECKSUM);
        CHECK(km_hid_build_write(out, 0x09, 0, data, 8) == KM_HID_OK);
        out[0] = 0x42;
        CHECK(km_hid_parse(out, &req) == KM_HID_ERR_HEADER);
        CHECK(km_hid_build_write(out, 0x09, 0, data, 8) == KM_HID_OK);
        out[4] = 57;
        CHECK(km_hid_parse(out, &req) == KM_HID_ERR_LEN);
        CHECK(km_hid_build_write(out, 0x09, 0, data, 57) == KM_HID_ERR_LEN);
        CHECK(km_hid_build_read(out, 0x08, 0, 57) == KM_HID_ERR_LEN);
        CHECK(km_hid_build(out, 0x00, 0x09, 0, 0, false, data, 1) == KM_HID_ERR_ARG);
        CHECK(km_hid_build_write(NULL, 0x09, 0, data, 1) == KM_HID_ERR_ARG);
        CHECK(km_hid_parse(NULL, &req) == KM_HID_ERR_ARG);
        /* A '_' packet with an oversized length must be rejected by our parser, even though
         * the stock firmware has no limit there (it would overflow a 64-byte buffer). */
        CHECK(km_hid_build_enter_boot(out) == KM_HID_OK);
        out[4] = 200;
        CHECK(km_hid_parse(out, &req) == KM_HID_ERR_LEN);
        /* Boot chunk limit is 32. */
        CHECK(km_boot_build_chunk(out, KM_BOOT_WRITE, 0, data, 33) == KM_HID_ERR_LEN);
        CHECK(km_boot_build_chunk(out, KM_BOOT_END, 0, data, 1) == KM_HID_ERR_ARG);
        CHECK(km_boot_build_finish(out, KM_BOOT_WRITE) == KM_HID_ERR_ARG);
    }

    /* LE24 offsets (0xE0 / 0xE1) include the third byte in the checksum. */
    {
        uint8_t out[KM_HID_REPORT_LEN];
        km_hid_req_t req;
        CHECK(km_hid_build_flash_read(out, 0x012345u, 56) == KM_HID_OK);
        CHECK_EQ(out[1], 0xE0);
        CHECK_EQ(out[4], 56);
        CHECK_EQ(out[5], 0x45);
        CHECK_EQ(out[6], 0x23);
        CHECK_EQ(out[7], 0x01);
        CHECK_EQ(out[3], (56 + 0x45 + 0x23 + 0x01) & 0xFF);
        CHECK(km_hid_parse(out, &req) == KM_HID_OK);
        CHECK_EQ(req.offset, 0x012345);
        CHECK(km_hid_build_flash_read(out, 0x80000u, 1) == KM_HID_ERR_ARG);   /* first byte past 512 KB */
        CHECK(km_hid_build_flash_read(out, 0x7FFFFu, 1) == KM_HID_OK);        /* last byte of flash */
        CHECK(km_hid_build_flash_read(out, 0x7FFFFu, 2) == KM_HID_ERR_ARG);   /* would run past the end */
        CHECK(km_hid_build_flash_read(out, 0x7FFC8u, 56) == KM_HID_OK);       /* exactly up to the end */
        CHECK(km_hid_build_flash_read(out, 0x0u, 57) == KM_HID_ERR_LEN);
    }

    /* Responses. */
    {
        uint8_t in[KM_HID_REPORT_LEN] = { 0 };
        const uint8_t *data = NULL;
        in[0] = KM_HID_RESP_OK;
        CHECK(km_hid_check_response(in, &data) == KM_HID_OK);
        CHECK(data == in + 8);
        in[0] = KM_HID_RESP_CSUM;
        CHECK(km_hid_check_response(in, &data) == KM_HID_ERR_CHECKSUM);
        in[0] = 0x00;
        CHECK(km_hid_check_response(in, &data) == KM_HID_ERR_RESPONSE);
    }

    /* Read-only classification: exactly the getters; every writer, reset and boot command is excluded. */
    {
        static const uint8_t ro[] = { 0x03, 0x04, 0x05, 0x07, 0x08, 0x0A, 0x0C, 0xA0, 0xA2, 0xA4, 0xA6,
                                      0xAA, 0xDE, 0xE0, 0xF1 };
        int is_ro[256] = { 0 };
        for (size_t i = 0; i < sizeof ro; i++) { is_ro[ro[i]] = 1; }
        int ok = 1;
        for (int c = 0; c < 256; c++) {
            if (km_cmd_is_read_only((uint8_t)c) != (is_ro[c] != 0)) { ok = 0; }
        }
        CHECK(ok);
        static const uint8_t writers[] = { 0x01, 0x02, 0x06, 0x09, 0x0B, 0x0D, 0x0E, 0xA1, 0xA3, 0xA5, 0xA7,
                                           0xA8, 0xA9, 0xB1, 0xDD, 0xE1, 0xEE, 0xF2, 0x80, 0x81, 0x82, 0x83, 0x84 };
        for (size_t i = 0; i < sizeof writers; i++) {
            CHECK(!km_cmd_is_read_only(writers[i]));
        }
    }
}

void test_flash_map(void)
{
    /* Layout sanity: aligned to the 8 KB erase unit, ascending, inside flash, app below the settings. */
    static const uint32_t sectors[] = {
        KM_CFG_ID_BLOCK, KM_CFG_BASE_INFO, KM_CFG_PROFILE, KM_CFG_CALIBRATION, KM_CFG_TRIGGER, KM_CFG_KEYMAP,
        KM_CFG_COLORS, KM_CFG_MACROS, KM_CFG_DKS, KM_CFG_MT, KM_CFG_TGL, KM_CFG_APP_DATA
    };
    for (size_t i = 0; i < sizeof sectors / sizeof sectors[0]; i++) {
        CHECK_EQ(sectors[i] % KM_FLASH_SECTOR, 0);
        CHECK(sectors[i] >= KM_APP_LIMIT && sectors[i] < KM_CFG_END);
        if (i > 0) { CHECK_EQ(sectors[i], sectors[i - 1] + KM_FLASH_SECTOR); }
    }
    CHECK_EQ(KM_APP_LIMIT - KM_APP_BASE, 128u * 1024u);
    CHECK(KM_BOOTLOADER_END == KM_APP_BASE);
    CHECK(KM_CFG_END <= KM_FLASH_BASE + KM_FLASH_SIZE);
    CHECK_EQ(KM_BOOT_FLAG_ADDR, 0x0802C000);
}
